from collections import deque
def f(g,bg,path):
    h,w=len(g),len(g[0]); seen=[[False]*w for _ in range(h)]; q=deque()
    for j in range(w):
        if g[0][j]!=path: q.append((0,j));seen[0][j]=True
        if g[-1][j]!=path: q.append((h-1,j));seen[h-1][j]=True
    for i in range(h):
        if g[i][0]!=path: q.append((i,0));seen[i][0]=True
        if g[i][-1]!=path: q.append((i,w-1));seen[i][w-1]=True
    while q:
        i,j=q.popleft(); 
        for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<h and 0<=nj<w and not seen[ni][nj] and g[ni][nj]==bg:
                seen[ni][nj]=True;q.append((ni,nj))
    return [[4 if (x==bg and not y) else x for x,y in zip(row,seen[row])] for row in range(h)]
# verify on demo
